def mk_grid(h,w,rb,cb,markers):
    g=[[0]*w for _ in range(h)]
    for r in rb:
        g[r]=[8]*w
    for c in cb:
        for r in range(h):g[r][c]=8
    for r,c,v in markers:g[r][c]=v
    return g
